const VALIDATION_CANDIDATES: readonly DiagramValidationCandidate[] = [
    { type: 'architecture' },
    { type: 'dependency' },
    { type: 'sequence' },
    { preset: 'flowchart', type: 'flow' },
    { preset: 'state', type: 'flow' },
